        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<BlogIdValueGenerator>();

        // Breaking Change 3: HasIndex is no longer supported for Cosmos in 9.0 (throws at model validation).
        // Fix: Remove the HasIndex call. Indexing in Cosmos is managed via the Azure portal/indexing policy.
        // (HasIndex call removed below)
